                                 AND    r.routingstatustypeid  IN  (8,2)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                 AND    IDAS.Activeflag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                 AND  (  coalesce(r.tosecurityusersid,IDAS.intakeuser)    =v_UserSID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                       OR   ( case  right(fromroleid,2)  when  'IW'  then  IDAS.InsertedBy      =v_UserSID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                                        when  'KW'  then  IDAS.InsertedBy      =v_UserSID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                 else  r.tosecurityusersid    =v_UserSID    end ) )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
